from datetime import datetime, timedelta, timezone

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.queries import TaskPage, TaskQuery, TaskQueryError, apply_query


@pytest.fixture
def now():
    return datetime(2025, 6, 15, 12, 0, 0, tzinfo=timezone.utc)


@pytest.fixture
def tasks(now):
    return [
        Task(id=1, title="Alpha", priority=TaskPriority.HIGH, created_at=now - timedelta(hours=3),
             tags=[Tag("work")]),
        Task(id=2, title="Beta", priority=TaskPriority.LOW, created_at=now - timedelta(hours=2),
             due_at=now - timedelta(hours=1), tags=[Tag("home")]),
        Task(id=3, title="Gamma", priority=TaskPriority.MEDIUM, created_at=now - timedelta(hours=1),
             status=TaskStatus.DONE, completed_at=now, tags=[Tag("work"), Tag("urgent")]),
        Task(id=4, title="Delta search", priority=TaskPriority.HIGH, created_at=now,
             due_at=now + timedelta(days=1), tags=[Tag("home")]),
    ]


class TestTaskQuery:
    def test_defaults(self):
        q = TaskQuery()
        assert q.sort == "created_at"
        assert q.limit == 20
        assert q.offset == 0
        assert q.descending is False

    def test_invalid_sort(self):
        with pytest.raises(TaskQueryError, match="sort must be one of"):
            TaskQuery(sort="invalid")

    def test_invalid_limit_zero(self):
        with pytest.raises(TaskQueryError, match="limit must be"):
            TaskQuery(limit=0)

    def test_invalid_limit_over_100(self):
        with pytest.raises(TaskQueryError, match="limit must be"):
            TaskQuery(limit=101)

    def test_invalid_offset_negative(self):
        with pytest.raises(TaskQueryError, match="offset must be"):
            TaskQuery(offset=-1)

    def test_tag_normalized(self):
        q = TaskQuery(tag="  Work  ")
        assert q.tag == "work"

    def test_invalid_tag(self):
        with pytest.raises(ValueError):
            TaskQuery(tag="bad tag!")

    def test_search_stripped(self):
        q = TaskQuery(search="  hello  ")
        assert q.search == "hello"

    def test_search_empty_becomes_none(self):
        q = TaskQuery(search="   ")
        assert q.search is None


class TestTaskPage:
    def test_has_more_true(self):
        page = TaskPage(items=[Task(id=1, title="T")], total=5, limit=2, offset=0)
        assert page.has_more is True

    def test_has_more_false(self):
        page = TaskPage(items=[Task(id=1, title="T")], total=1, limit=20, offset=0)
        assert page.has_more is False


class TestApplyQuery:
    def test_no_filters(self, tasks, now):
        page = apply_query(tasks, TaskQuery(), now)
        assert page.total == 4
        assert len(page.items) == 4

    def test_filter_by_status(self, tasks, now):
        page = apply_query(tasks, TaskQuery(status=TaskStatus.DONE), now)
        assert page.total == 1
        assert page.items[0].id == 3

    def test_filter_by_tag(self, tasks, now):
        page = apply_query(tasks, TaskQuery(tag="work"), now)
        assert page.total == 2
        assert {t.id for t in page.items} == {1, 3}

    def test_filter_by_search(self, tasks, now):
        page = apply_query(tasks, TaskQuery(search="search"), now)
        assert page.total == 1
        assert page.items[0].id == 4

    def test_filter_by_search_case_insensitive(self, tasks, now):
        page = apply_query(tasks, TaskQuery(search="ALPHA"), now)
        assert page.total == 1
        assert page.items[0].id == 1

    def test_filter_overdue_true(self, tasks, now):
        page = apply_query(tasks, TaskQuery(overdue=True), now)
        assert page.total == 1
        assert page.items[0].id == 2

    def test_filter_overdue_false(self, tasks, now):
        page = apply_query(tasks, TaskQuery(overdue=False), now)
        # Tasks 1, 3, 4 are not overdue (1 no due, 3 done, 4 future)
        assert page.total == 3

    def test_sort_by_priority(self, tasks, now):
        page = apply_query(tasks, TaskQuery(sort="priority"), now)
        priorities = [t.priority for t in page.items]
        assert priorities == [TaskPriority.HIGH, TaskPriority.HIGH, TaskPriority.MEDIUM, TaskPriority.LOW]

    def test_sort_by_title(self, tasks, now):
        page = apply_query(tasks, TaskQuery(sort="title"), now)
        titles = [t.title for t in page.items]
        assert titles == ["Alpha", "Beta", "Delta search", "Gamma"]

    def test_sort_descending(self, tasks, now):
        page = apply_query(tasks, TaskQuery(sort="title", descending=True), now)
        titles = [t.title for t in page.items]
        assert titles == ["Gamma", "Delta search", "Beta", "Alpha"]

    def test_sort_by_due_at(self, tasks, now):
        page = apply_query(tasks, TaskQuery(sort="due_at"), now)
        # None due_at sorts last
        assert page.items[-1].due_at is None or page.items[-2].due_at is None

    def test_pagination_limit(self, tasks, now):
        page = apply_query(tasks, TaskQuery(limit=2), now)
        assert len(page.items) == 2
        assert page.total == 4
        assert page.has_more is True

    def test_pagination_offset(self, tasks, now):
        page = apply_query(tasks, TaskQuery(limit=2, offset=2), now)
        assert len(page.items) == 2
        assert page.offset == 2
        assert page.has_more is False

    def test_pagination_offset_beyond(self, tasks, now):
        page = apply_query(tasks, TaskQuery(offset=10), now)
        assert page.items == []
        assert page.total == 4
        assert page.has_more is False

    def test_combined_filters(self, tasks, now):
        page = apply_query(tasks, TaskQuery(status=TaskStatus.PENDING, tag="home"), now)
        assert page.total == 2
        assert {t.id for t in page.items} == {2, 4}

